'use strict';
// One private catalogue across this user's chats in the active project/domain.
const knowledgeCardViews=new Map(),knowledgeCardEdits=new Map();
let knowledgeCardSavePromise=null;
const knowledgeCardDefaults={finding:{label:'Finding',fields:{scope:'Scope and situation',evidence_notes:'Evidence notes',implications:'Implications',limits:'Evidence limits'}},'user-situation':{label:'User situation',fields:{people:'People and role',job:'Job to be done',situation:'Situation',triggers:'Triggers',pains:'Pains and bottlenecks',gains:'Gains sought',boundaries:'Boundaries',dependencies:'Dependencies'}},'user-flow':{label:'User flow',fields:{people:'People and role',trigger:'Starting trigger',steps:'Steps and actions',branches:'Branches and exceptions',obstacles:'Obstacles and bottlenecks',outcome:'Desired outcome'}},'user-story':{label:'User story',fields:{role:'As a',need:'I need',benefit:'So that',acceptance_criteria:'Proposed acceptance criteria',conditions:'Conditions and limits'}},artifact:{label:'Artifact',fields:{artifact_type:'Artifact type · e.g. Prototype',version_label:'Version or variant',location:'File or tool location',purpose:'What this artifact demonstrates',review_status:'Review or testing status',limits:'Limits and open questions'}},implication:{label:'Implication',fields:{consequence:'What this could change',conditions:'When it applies',limits:'Limits and uncertainty'}},hypothesis:{label:'Hypothesis',fields:{test:'What would test this',conditions:'When it applies',limits:'Limits and uncertainty'}},challenge:{label:'Challenge',fields:{question:'What needs reconsideration',consequence:'Why it matters',limits:'Limits and uncertainty'}},dependency:{label:'Dependency',fields:{condition:'Required condition',consequence:'What depends on it',limits:'Limits and uncertainty'}},'performance-goal':{label:'Performance goal',fields:{outcome:'Outcome sought',measure:'How it could be measured',baseline:'Known baseline',target:'Proposed target',accountable_owner:'Accountable role'}},question:{label:'Open question',fields:{decision_needed:'What would resolve it',limits:'Limits and uncertainty'}},note:{label:'Working note',fields:{scope:'Scope and applicability',limits:'Limits and uncertainty'}}};
const knowledgeCardHints={"finding": "An observation or conclusion with a source and stated limits.", "user-situation": "Who is doing what, in which situation, and what gets in the way.", "user-flow": "Actions, decisions and exceptions leading to an outcome.", "user-story": "A proposed capability expressed as a role, need and benefit.", "artifact": "A specific work product or prototype version. Link its retained file.", "implication": "What a finding or condition may change for the project.", "hypothesis": "A testable explanation awaiting evidence.", "challenge": "A reason to reconsider a claim, requirement or approach.", "dependency": "A condition or input needed for other work to succeed.", "performance-goal": "An intended outcome and a proposed way to measure it.", "question": "An unresolved question and what would resolve it.", "note": "A captured idea. Choose a more specific type as its meaning becomes clear."};
function knowledgeCardInfo(){return chatInfo().knowledge_cards||{types:knowledgeCardDefaults,relations:{'applies-to':'Applies to','supported-by':'Supported by',supports:'Supports',challenges:'Challenges',refines:'Refines','depends-on':'Depends on',constrains:'Constrains',informs:'Informs',measures:'Measures'},catalogue:[],targets:[]};}
function knowledgeCardCollectionName(){return knowledgeCardInfo().label||domainProfile().config.label+' building blocks';}
function knowledgeCardName(){return knowledgeCardInfo().card_label||domainProfile().config.label+' building block';}
function knowledgeCards(){return (chatInfo().implications||[]).filter(r=>r.body.owner===undefined||r.body.owner===state.actor);}
function knowledgeCardMeta(row){return knowledgeCardInfo().catalogue.find(v=>v.ref.id===row.ref.id)||{type:row.body.card?.type||({'open-question':'question','challenge-requirement':'challenge','challenge-intent':'challenge'}[row.body.payload.kind]||'implication'),relations:[],backlinks:[]};}
function knowledgeCardView(){const key=chatSession();if(!knowledgeCardViews.has(key))knowledgeCardViews.set(key,{search:'',type:'',status:'held',open:null});return knowledgeCardViews.get(key);}
function knowledgeCardDisclosure(section){return knowledgeCardView().sections?.[section]?'open':'';}
function knowledgeCardEditKey(id){return chatSession()+'|'+id;}
function knowledgeCardDraft(row){const key=knowledgeCardEditKey(row.ref.id),old=knowledgeCardEdits.get(key);if(old)return old;const b=row.body,p=b.payload;const value={expected:row.ref.id==='NEW-CARD'?null:row.ref,conversation:(chatInfo().threads||[]).find(t=>t.ref.id===b.conversation)?.ref,type:knowledgeCardMeta(row).type,title:p.title,statement:p.statement,rationale:p.rationale||'',fields:{...(b.card?.fields||{})},relations:(b.card?.relations||[]).map(r=>({...r,ref:{...r.ref}})),evidence:(p.evidence||[]).map(e=>({...e})),status:b.status,request_id:row.ref.id==='NEW-CARD'?crypto.randomUUID():undefined,dirty:false};knowledgeCardEdits.set(key,value);return value;}
function hasUnsavedKnowledgeCards(){const prefix=chatSession()+'|';return (typeof hasUnsavedIntegrityGaps==='function'&&hasUnsavedIntegrityGaps())||[...knowledgeCardEdits].some(([k,v])=>k.startsWith(prefix)&&v.dirty);}
function knowledgeCardRelated(row){const m=knowledgeCardMeta(row);return m.relations.length?`<p class="knowledge-card-related caption">${m.relations.slice(0,2).map(l=>`${esc(knowledgeCardInfo().relations[l.relation])} <a class="item-title-link" href="#main" data-action="kc-related" data-id="${esc(label(l.ref))}">${esc(referenceText(l.ref,{ref:l.ref,body:{title:l.title}}))}</a>${l.changed?' · updated':''}`).join('<br>')}${m.relations.length>2?`<br>+ ${m.relations.length-2} more`:''}</p>`:'';}
function knowledgeCardRow(row){if(typeof kcCard==='function')return kcCard(row);const p=row.body.payload,m=knowledgeCardMeta(row),e=implicationSupport(row),shared=m.shared_source&&label(m.shared_source)===label(row.ref);return `<article class="knowledge-card-row"><h3><a href="#main" class="item-title-link" data-action="kc-open" data-id="${esc(row.ref.id)}">${esc(p.title)}</a></h3><p class="caption">${esc(knowledgeCardInfo().types[m.type]?.label||m.type)}${m.type==='artifact'&&row.body.card?.fields.artifact_type?' · '+esc(row.body.card.fields.artifact_type):''} · ${row.body.status==='held'?'Saved':row.body.status==='dismissed'?'Archived':'Suggested'} · v${row.ref.revision}${m.shared?shared?' · Shared copy available':' · Private changes since sharing':''}</p><p class="knowledge-card-excerpt">${esc(p.statement.slice(0,170))}${p.statement.length>170?'…':''}</p>${knowledgeCardRelated(row)}${e.status==='earlier-basis'?'<p class="caption">Supporting inputs changed · review when using this block.</p>':''}</article>`;}
function knowledgeCardList(){return (typeof integrityGapList==='function'&&knowledgeCardView().type==='gap'?'':knowledgeOrdinaryCardList())+(typeof integrityGapList==='function'?integrityGapList():'');}
function knowledgeCardTypeGrid(){return knowledgeOrdinaryTypeGrid()+(typeof integrityGapTypeTile==='function'?integrityGapTypeTile():'');}
function knowledgeOrdinaryCardList(){const v=knowledgeCardView(),all=knowledgeCards(),q=v.search.toLocaleLowerCase(),rows=all.filter(r=>(!v.status||r.body.status===v.status)&&(!v.type||knowledgeCardMeta(r).type===v.type)&&(!q||[r.ref.id,r.body.payload.title,r.body.payload.statement,r.body.payload.rationale,JSON.stringify(r.body.card?.fields||{})].join(' ').toLocaleLowerCase().includes(q)));return `<p class="caption" role="status">${rows.length} ${rows.length===1?'block':'blocks'}${v.status==='held'?' saved in this domain':''}</p>${rows.map(knowledgeCardRow).join('')||`<p class="caption">${all.length?v.type&&!v.search?'No '+knowledgeCardInfo().types[v.type].label+' blocks here yet. Use ＋ to add one.':'No blocks match these filters.':'Select text in chat to save a building block, or add one here.'}</p>`}`;}
const knowledgeCardIconPaths={finding:'M9 3h6l2 4v6l-3 3v4h-4v-4l-3-3V7z M9 9h6', 'user-situation':'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M5 21v-3a7 7 0 0 1 14 0v3', 'user-flow':'M3 4h5v5H3z M16 15h5v5h-5z M8 6h10v9 M15 12l3 3 3-3', 'user-story':'M4 4h16v13H9l-5 4z M8 8h8 M8 12h6', artifact:'M4 4h16v16H4z M8 4v4h8V4 M7 16l4-5 3 3 2-2 3 4', hypothesis:'M9 3h6 M10 3v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3 M8 14h8', implication:'M4 6h6v6H4z M10 9h7v10 M14 16l3 3 3-3', challenge:'M12 3l10 18H2z M12 9v5 M12 17v1', dependency:'M9 15l6-6 M7 14H6a4 4 0 0 1 0-8h5 M17 10h1a4 4 0 0 1 0 8h-5', 'performance-goal':'M12 2a10 10 0 1 0 10 10 M12 7a5 5 0 1 0 5 5 M12 12L22 2 M16 2h6v6', question:'M9 7a3 3 0 1 1 5 2c-2 1-2 2-2 4 M12 17v1 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20', note:'M5 3h10l4 4v14H5z M15 3v5h4 M8 12h8 M8 16h6'};
const knowledgeTileLabels={'design-decision':'Decision','evaluation-result':'Evaluation','user-situation':'Situation','user-flow':'User flow','user-story':'User story','performance-goal':'Goal',question:'Question',note:'Note'};
// D013: this team's types lead; every other type stays available.
function knowledgeTypeEntries(){const info=knowledgeCardInfo(),first=info.preferred||[],all=Object.entries(info.types||{});return [...first.map(k=>all.find(([key])=>key===k)).filter(Boolean),...all.filter(([k])=>!first.includes(k))];}
function knowledgeCardTypeChoices(current=''){return knowledgeTypeEntries().filter(([key])=>key!=='implication'||current==='implication');}
function knowledgeOrdinaryTypeGrid(){const v=knowledgeCardView(),all=knowledgeCards().filter(r=>!v.status||r.body.status===v.status);const info=knowledgeCardInfo(),first=new Set(info.preferred||[]),families=info.families||{};const tile=([key,t])=>{const count=all.filter(r=>knowledgeCardMeta(r).type===key).length;return `<button type="button" class="knowledge-type-tile" title="${esc(t.label)}" data-action="kc-filter-type" data-id="${esc(key)}" aria-pressed="${v.type===key}" aria-label="${esc(t.label)}, ${count} ${v.status==='held'?'saved ':''}${count===1?'block':'blocks'}"><span class="knowledge-type-top"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${knowledgeCardIconPaths[key]||knowledgeCardIconPaths.note}"/></svg><span class="knowledge-type-count" aria-hidden="true">${count}</span></span><span>${esc(knowledgeTileLabels[key]||t.label)}</span></button>`;};
 const used=key=>all.some(r=>knowledgeCardMeta(r).type===key),shown=knowledgeTypeEntries().filter(([key])=>key!=='implication'||used(key)).filter(([key])=>!v.type||v.type===key);
 if(v.type||!Object.keys(families).length)return shown.map(tile).join('');
 // Families group the types. A type outside this team's set appears only once it holds a block, or under "More types".
 const main=shown.filter(([key])=>!first.size||first.has(key)||used(key)),more=shown.filter(e=>!main.includes(e));
 return Object.entries(families).map(([f,label])=>{const rows=main.filter(([,t])=>t.family===f);return rows.length?`<h4 class="knowledge-family">${esc(label)}</h4>${rows.map(tile).join('')}`:'';}).join('')+(more.length?`<details class="knowledge-more-types"><summary>More types (${more.length})</summary><div class="knowledge-card-types">${more.map(tile).join('')}</div></details>`:'');}
function knowledgeCardFilterTitle(){const v=knowledgeCardView();return v.type?`<button type="button" class="compact-text-action" data-action="kc-filter-type" data-id="">All categories</button>`:'<span>All block types</span>';}
function refreshKnowledgeCatalogue(){const grid=document.getElementById('knowledge-card-type-grid'),list=document.getElementById('knowledge-card-catalogue'),title=document.getElementById('knowledge-card-filter-title');if(grid){grid.innerHTML=knowledgeCardTypeGrid();grid.classList?.toggle('is-filtered',Boolean(knowledgeCardView().type));}if(list)list.innerHTML=knowledgeCardList();if(title)title.innerHTML=knowledgeCardFilterTitle();}
function knowledgeCardsPanel(){const v=knowledgeCardView(),row=v.newCard||knowledgeCards().find(r=>r.ref.id===v.open);return `<aside id="project-implications-panel" class="domain-context-panel knowledge-cards-panel" aria-label="${esc(knowledgeCardCollectionName())}"><header class="domain-panel-header"><div><h2>${esc(knowledgeCardCollectionName())}</h2><p class="caption">Private</p></div><button type="button" class="quiet icon" data-action="dchat-panel-close" aria-label="Close ${esc(knowledgeCardCollectionName())}">✕</button></header><div class="domain-context-body">${knowledgeCarryChip()}${typeof integrityGapCurrent==='function'&&integrityGapCurrent()?integrityGapDetail():row?(typeof kcDossierActive==='function'&&kcDossierActive(row)?kcDossier(row):knowledgeCardEditor(row)):`${typeof kcCollectionSummary==='function'?kcCollectionSummary():''}<div class="knowledge-card-catalogue-head"><label class="form-field" for="knowledge-card-search"><span class="sr-only">Search building blocks</span><input type="search" id="knowledge-card-search" placeholder="Search blocks" value="${esc(v.search)}"></label><button type="button" class="compact-text-action" data-action="kc-new" aria-label="Add ${esc(knowledgeCardName())}" title="Add ${esc(knowledgeCardName())}">＋</button></div><div id="knowledge-card-type-grid" class="knowledge-card-types ${v.type?'is-filtered':''}" role="group" aria-label="Block categories">${knowledgeCardTypeGrid()}</div><div class="knowledge-card-filters"><div id="knowledge-card-filter-title" class="knowledge-card-filter-title">${knowledgeCardFilterTitle()}</div><label><span class="sr-only">Show</span><select id="knowledge-card-status" aria-label="Show">${[['held','Saved'],['suggested','Suggested'],['dismissed','Archived'],['','All blocks']].map(([k,t])=>`<option value="${k}" ${v.status===k?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="knowledge-card-catalogue">${knowledgeCardList()}</div><details class="development-assessments"><summary>Work assessments</summary>${objectiveCoverage()}${chatAlignmentRows().length?'<button type="button" class="compact-text-action" data-action="dchat-alignment-panel">Inspect requirement assessments</button>':''}</details>`}</div></aside>`;}
function knowledgeCardDetailsTitle(type){return type==='user-situation'?'People, job & situation':type==='artifact'?'Artifact version & review':'Details';}
function knowledgeCardFields(d){const all=Object.entries(knowledgeCardInfo().types[d.type]?.fields||{}),field=([key,title])=>`<label class="form-field">${knowledgeDropLabel("fields."+key,title)}<textarea name="card-field-${key}" rows="2" maxlength="2000">${esc(d.fields[key]||'')}</textarea></label>`,applies=all.filter(([k])=>k.startsWith('applies_'));return all.filter(([k])=>!k.startsWith('applies_')).map(field).join('')+(applies.length?`<fieldset class="knowledge-applies"><legend>Where this applies</legend><p class="caption">Helps a later project judge whether this fits its situation.</p>${applies.map(field).join('')}</fieldset>`:'');}
function knowledgeCardTargetOptions(selected,sourceOnly=false,id=null){const items=(knowledgeCardInfo().targets||[]).filter(t=>(!sourceOnly||t.source)&&t.ref.id!==id);if(selected&&!items.some(t=>label(t.ref)===label(selected)))items.unshift({ref:selected});return `<option value="">Choose ${sourceOnly?'a source':'a related block or project item'}</option>`+items.map(t=>`<option value="${esc(label(t.ref))}" ${selected&&label(t.ref)===label(selected)?'selected':''}>${esc(referenceText(t.ref,t.title?{ref:t.ref,body:{title:t.title}}:undefined))}${t.private?' · Private':''}</option>`).join('');}
function knowledgeCardLinksEditor(row,d){return `<div id="knowledge-card-links">${d.relations.map((l,i)=>`<fieldset class="knowledge-card-link"><legend class="sr-only">Related item ${i+1}</legend><label><span>Relationship</span><select name="link-type-${i}">${Object.entries(knowledgeCardInfo().relations).map(([k,t])=>`<option value="${k}" ${l.relation===k?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label><span>Related item</span><select name="link-ref-${i}" required>${knowledgeCardTargetOptions(l.ref,false,row.ref.id)}</select></label><label><span>Why these are connected</span><textarea name="link-reason-${i}" rows="2" maxlength="800" required>${esc(l.rationale)}</textarea></label><label><span>When this applies</span><textarea name="link-conditions-${i}" rows="2" maxlength="800">${esc(l.conditions)}</textarea></label><button type="button" class="compact-text-action remove-control" data-action="kc-remove-link" data-id="${i}" aria-label="Remove link" title="Remove link"><span aria-hidden="true">×</span></button></fieldset>`).join('')}</div><button type="button" class="compact-text-action" data-action="kc-add-link" ${d.relations.length>=12?'disabled':''}>＋ Add link</button>`;}
function knowledgeCardEvidenceEditor(d){return `${d.evidence.map((e,i)=>`<fieldset class="knowledge-card-link"><legend class="sr-only">Evidence ${i+1}</legend><label><span>Source</span><select name="evidence-source-${i}" required>${knowledgeCardTargetOptions(e.source?knowledgeParseRef(e.source):null,true)}</select></label><label><span>Exact source passage</span><textarea name="evidence-quote-${i}" rows="3" maxlength="500">${esc(e.quote)}</textarea></label><label><span>PDF page · if citing a retained page instead of text</span><input type="number" name="evidence-page-${i}" min="1" value="${e.page||''}"></label><button type="button" class="compact-text-action remove-control" data-action="kc-remove-evidence" data-id="${i}" aria-label="Remove evidence" title="Remove evidence"><span aria-hidden="true">×</span></button></fieldset>`).join('')}<button type="button" class="compact-text-action" data-action="kc-add-evidence" ${d.evidence.length>=4?'disabled':''}>＋ Add evidence</button><p class="caption">Use exact source text or a retained PDF page. Saved chat wording is not independent evidence.</p>`;}
function knowledgeCardEditor(row){const d=knowledgeCardDraft(row),m=knowledgeCardMeta(row),selected=submissionDraft().implication_refs.find(v=>v.id===row.ref.id);return `<div class="knowledge-card-detail"><a href="#main" class="item-title-link" data-action="kc-back">← Blocks</a><form id="knowledge-card-editor" data-card-id="${esc(row.ref.id)}"><div class="knowledge-card-heading"><h3>${esc(d.title||'New '+knowledgeCardName())}</h3><p class="caption">${row.ref.id==='NEW-CARD'?'Not saved yet':'Version '+row.ref.revision} · ${m.shared?'Private working block · shared copy retained':'Private working block'}</p></div><label class="form-field"><span>Type</span><select name="card-type" id="knowledge-card-editor-type" aria-describedby="knowledge-card-type-hint">${knowledgeCardTypeChoices(d.type).map(([k,t])=>`<option value="${k}" ${d.type===k?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><p class="caption" id="knowledge-card-type-hint">${esc(knowledgeCardInfo().types[d.type]?.hint||knowledgeCardHints[d.type])}</p><label class="form-field"><span>Title</span><input name="card-title" maxlength="200" required value="${esc(d.title)}"></label><label class="form-field">${knowledgeDropLabel("statement","What this block captures")}<textarea name="card-statement" rows="5" maxlength="4000" required>${esc(d.statement)}</textarea></label><label class="form-field">${knowledgeDropLabel("rationale","Why it matters and what remains uncertain")}<textarea name="card-rationale" rows="3" maxlength="1500">${esc(d.rationale)}</textarea></label><details class="knowledge-card-section" data-knowledge-disclosure="context" ${knowledgeCardDisclosure('context')}><summary>${knowledgeCardDetailsTitle(d.type)}</summary><div id="knowledge-card-fields">${knowledgeCardFields(d)}</div></details><details class="knowledge-card-section" data-knowledge-disclosure="links" ${knowledgeCardDisclosure('links')}><summary>Related blocks & project items (${d.relations.length})</summary>${m.relations.some(l=>l.changed)?'<p class="caption">A related item has a newer version. The saved relationship retains its earlier reference.</p>':''}${d.relations.length?'':'<p class="caption">No links yet. Connect what this depends on, supports or changes.</p>'}${knowledgeCardLinksEditor(row,d)}${m.backlinks.length?`<p class="caption">Linked from: ${m.backlinks.map(l=>`<a href="#main" class="item-title-link" data-action="kc-open" data-id="${esc(l.ref.id)}">${esc(l.title)}</a>`).join(' · ')}</p>`:''}</details><details class="knowledge-card-section" data-knowledge-disclosure="evidence" ${knowledgeCardDisclosure('evidence')}><summary>Evidence (${d.evidence.length})</summary>${knowledgeCardEvidenceEditor(d)}${row.body.evidence_review?implicationEvidence(row):''}</details>${row.ref.id==='NEW-CARD'?'':sourceDetails([row.ref,...d.relations.map(l=>l.ref),...d.evidence.map(e=>knowledgeParseRef(e.source))])}${knowledgeCaptureHistory(row)}${row.body.origin_selection?`<details class="knowledge-card-section" data-knowledge-disclosure="origin" ${knowledgeCardDisclosure('origin')}><summary>Saved from chat</summary><blockquote>${esc(row.body.origin_selection.text)}</blockquote><p class="caption">${row.body.origin_selection.role==='user'?'Authored message':'AI partner wording'} · retained privately as provenance.</p></details>`:''}<div class="knowledge-card-save"><button type="submit" class="small">Save block</button>${row.ref.id==='NEW-CARD'?'<button type="button" class="compact-text-action" data-action="kc-discard">Discard</button>':''}<span class="caption" id="knowledge-card-save-status" role="status">${row.ref.id==='NEW-CARD'?'Not saved yet':d.dirty?'Unsaved changes':'Saved privately'}</span></div></form>${row.ref.id==='NEW-CARD'?'':`<div class="knowledge-card-use"><button type="button" class="compact-text-action" data-action="kc-select" data-id="${esc(row.ref.id)}">${selected?label(selected)===label(row.ref)?'Remove from deliverable':'Use latest version in deliverable':'Select for deliverable'}</button><p class="caption">${selected?'Selected for the current deliverable and its context packet.':'Sharing requires a selected deliverable and publication preview.'}</p></div><details class="knowledge-card-section" data-knowledge-disclosure="history" ${knowledgeCardDisclosure('history')}><summary>History</summary><button type="button" class="compact-text-action" data-action="kc-history" data-id="${esc(row.ref.id)}">View saved versions</button>${m.shared?`<p><a href="#main" class="item-title-link" data-action="kc-shared" data-id="${esc(label(m.shared))}">View shared copy · v${m.shared.revision}</a></p>`:''}<button type="button" class="compact-text-action" data-action="kc-archive" data-id="${esc(row.ref.id)}">${row.body.status==='dismissed'?'Restore block':'Archive block'}</button></details><div class="knowledge-card-assess"><button type="button" class="compact-text-action" data-action="kc-assess" data-id="${esc(row.ref.id)}">Assess block</button></div>`}</div>`;}
function knowledgeParseRef(value){const at=value.lastIndexOf(':v');if(at<0)return null;return {id:value.slice(0,at),revision:Number(value.slice(at+2))};}
function captureKnowledgeEditor(){const form=document.getElementById('knowledge-card-editor');if(!form)return null;const row=knowledgeCardView().newCard||knowledgeCards().find(r=>r.ref.id===form.dataset.cardId);if(!row)return null;const d=knowledgeCardDraft(row),fd=new FormData(form);d.title=fd.get('card-title');d.statement=fd.get('card-statement');d.rationale=fd.get('card-rationale');for(const k of Object.keys(knowledgeCardInfo().types[d.type]?.fields||{}))d.fields[k]=fd.get('card-field-'+k)||'';d.relations=d.relations.map((l,i)=>({relation:fd.get('link-type-'+i)||l.relation,ref:knowledgeParseRef(fd.get('link-ref-'+i)||'')||l.ref,rationale:fd.get('link-reason-'+i)||'',conditions:fd.get('link-conditions-'+i)||''}));d.evidence=d.evidence.map((e,i)=>({source:fd.get('evidence-source-'+i)||e.source,quote:fd.get('evidence-quote-'+i)||'',page:fd.get('evidence-page-'+i)?Number(fd.get('evidence-page-'+i)):null}));return {row,d};}
async function saveKnowledgeCardEditor(){if(knowledgeCardSavePromise)return knowledgeCardSavePromise;const value=captureKnowledgeEditor();if(!value)return;const {row,d}=value;if(!d.dirty&&d.status!=='suggested')return;const form=document.getElementById('knowledge-card-editor');if(form?.reportValidity&&!form.reportValidity())throw Error('Complete the block title, statement and any added links before saving.');const data={...d,type:d.type,fields:Object.fromEntries(Object.keys(knowledgeCardInfo().types[d.type].fields).map(k=>[k,d.fields[k]||''])),status:d.status==='suggested'?'held':d.status};delete data.dirty;knowledgeCardSavePromise=(async()=>{const out=await command('knowledge-card-save',data);await load();knowledgeCardEdits.delete(knowledgeCardEditKey(row.ref.id));knowledgeCardView().newCard=null;knowledgeCardView().open=out.ref.id;return out;})();try{return await knowledgeCardSavePromise;}finally{knowledgeCardSavePromise=null;}}
async function saveKnowledgeCardDrafts(){await saveKnowledgeCardEditor();}
async function createKnowledgeCard(capture=null){await saveDevelopmentEditors();await saveSubmission();await chatEnsure();if(!capture){const v=knowledgeCardView();v.newCard={ref:{id:'NEW-CARD',revision:0},body:{owner:state.actor,conversation:chatThread().ref.id,status:'held',card:{type:v.type||'note',fields:{},relations:[]},payload:{kind:'open-question',title:'',statement:'',rationale:'',targets:[],evidence:[]}}};v.open='NEW-CARD';knowledgeCardEdits.delete(knowledgeCardEditKey('NEW-CARD'));domainPanels.set(chatKey(),'implications');render();return;}return openKnowledgeCapture(capture,false);}
async function saveKnowledgePassage(capture){if(capture.key!==chatKey())throw Error('Select the passage again in its original chat.');hideThoughtSelection();return createKnowledgeCard(capture);}
function knowledgeSubmissionRows(){return knowledgeCards().filter(r=>r.body.status==='held');}
function knowledgeSubmissionSources(){const result=[...(chatWork()?.body.source_refs||[])],selected=new Set(submissionDraft().implication_refs.map(r=>r.id));for(const r of knowledgeCards().filter(r=>selected.has(r.ref.id))){for(const e of r.body.payload.evidence||[]){const ref=knowledgeParseRef(e.source);if(!result.some(v=>label(v)===label(ref))&&knowledgeCardInfo().targets.some(v=>label(v.ref)===label(ref)&&v.source))result.push(ref);}for(const l of r.body.card?.relations||[]){if(knowledgeCardInfo().targets.some(t=>label(t.ref)===label(l.ref)&&t.source)&&!result.some(v=>label(v)===label(l.ref)))result.push(l.ref);}}return result;}
function knowledgeSelectionList(held,d){return held.map(r=>{const selected=d.implication_refs.find(v=>v.id===r.ref.id);return `<label class="chat-check"><input type="checkbox" data-submission-implication="${esc(r.ref.id)}" ${selected?'checked':''}><span>${esc(r.body.payload.title)}<small>${esc(knowledgeCardInfo().types[knowledgeCardMeta(r).type]?.label||'Card')}${selected&&label(selected)!==label(r.ref)?' · Selected version changed · reselect to use the latest':''}</small></span></label>`;}).join('')||'<p class="caption">Save blocks from chat or add one in Building blocks.</p>';}
async function knowledgeCardAction(action,id){if(action==='kc-assess'){knowledgeCardAssessment(id);return true;}if(await knowledgePlacementAction(action,id))return true;if(action==='kc-capture-back'){const text=document.getElementById('knowledge-capture-text');if(text)knowledgeCapture.after=text.value;const summary=document.querySelector('#modal [name=summary]');if(summary)knowledgeCapture.summary=summary.value;knowledgeCaptureChoose();return true;}if(!action.startsWith('kc-'))return false;const v=knowledgeCardView();if(action==='kc-filter-type'){v.type=v.type===id?'':id;refreshKnowledgeCatalogue();return true;}if(!['kc-discard','kc-add-link','kc-remove-link','kc-add-evidence','kc-remove-evidence'].includes(action))await saveKnowledgeCardEditor();if(action==='kc-discard'){knowledgeCardEdits.delete(knowledgeCardEditKey('NEW-CARD'));v.newCard=null;v.open=null;render();}if(action==='kc-new')await createKnowledgeCard();if(action==='kc-open'){v.newCard=null;v.open=id;v.dossier=id;v.dossierTab='profile';render();}if(action==='kc-back'){v.newCard=null;v.open=null;v.dossier=null;render();}if(action==='kc-edit'){v.dossier=null;render();}if(action==='kc-dossier-tab'){v.dossierTab=id;render();}if(action==='kc-edit-section'){const [cid,section]=String(id).split('|');v.newCard=null;v.open=cid;v.dossier=null;if(section&&section!=='type'){v.sections={...(v.sections||{}),[section]:true};}render();const el=section==='type'?document.getElementById?.('knowledge-card-editor-type'):document.querySelector?.(`[data-knowledge-disclosure="${section}"]`);el?.scrollIntoView?.({block:'center'});el?.focus?.();}if(action==='kc-related'){const raw=knowledgeParseRef(id),target=knowledgeCards().find(r=>label(r.ref)===id);if(target){v.open=target.ref.id;v.dossier=target.ref.id;v.dossierTab='profile';render();}else if(raw){const out=await command('knowledge-card-link-read',{ref:raw});modal(out.record.body.title||out.record.body.payload?.title||'Related context',knowledgeLinkContent(out.record),null,null,{className:'settings-dialog'});}}if(['kc-add-link','kc-remove-link','kc-add-evidence','kc-remove-evidence'].includes(action)){const value=captureKnowledgeEditor();if(!value)return true;const {d}=value;if(action==='kc-add-link')d.relations.push({relation:'informs',ref:null,rationale:'',conditions:''});if(action==='kc-remove-link')d.relations.splice(Number(id),1);if(action==='kc-add-evidence')d.evidence.push({source:'',quote:'',page:null});if(action==='kc-remove-evidence')d.evidence.splice(Number(id),1);d.dirty=true;render();}if(action==='kc-select'){await saveSubmission();const r=knowledgeCards().find(r=>r.ref.id===id),d=submissionDraft(),old=d.implication_refs.find(v=>v.id===id);d.implication_refs=d.implication_refs.filter(v=>v.id!==id);if(!old||label(old)!==label(r.ref))d.implication_refs.push(r.ref);d.dirty=true;await saveSubmission();render();}if(action==='kc-archive'){const sd=submissionDraft();if(sd.implication_refs.some(r=>r.id===id)){sd.implication_refs=sd.implication_refs.filter(r=>r.id!==id);sd.dirty=true;await saveSubmission();}const r=knowledgeCards().find(r=>r.ref.id===id);await command('knowledge-card-save',{expected:r.ref,status:r.body.status==='dismissed'?'held':'dismissed'});await load();knowledgeCardEdits.delete(knowledgeCardEditKey(id));v.open=null;render();}if(action==='kc-history'){const row=knowledgeCards().find(r=>r.ref.id===id),out=await command('knowledge-card-read',{ref:row.ref});modal('Block history',`<p>${esc(row.body.payload.title)}</p>${out.history.map(h=>`<p><a href="#main" class="item-title-link" data-action="kc-version" data-id="${esc(label(h.ref))}">Version ${h.ref.revision}</a> <span class="caption">${esc(date(h.at))}</span></p>`).join('')}`);}if(action==='kc-version'){const out=await command('knowledge-card-read',{ref:knowledgeParseRef(id)}),r=out.record;modal('Earlier block version',`<p class="caption">Version ${r.ref.revision} · Read only</p>${sourceDetails(r.ref)}<h3>${esc(r.body.payload.title)}</h3>${para(r.body.payload.statement)}${para(r.body.payload.rationale)}${Object.entries(r.body.card?.fields||{}).map(([k,t])=>`<h4>${esc(knowledgeCardInfo().types[knowledgeCardMeta(r).type]?.fields[k]||k)}</h4>${para(t)}`).join('')}`);}if(action==='kc-shared'){const r=records('knowledge-card').find(r=>label(r.ref)===id);modal('Shared building block',r?`<p class="caption">Shared for review · v${r.ref.revision}</p>${sourceDetails(r.ref)}<h3>${esc(r.body.title)}</h3>${para(r.body.statement)}${para(r.body.rationale)}<p class="caption">${esc(r.body.authority)}</p>`:'<p>Inspect this exact shared block in its context packet.</p>');}return true;}
document.addEventListener('input',e=>{if(e.target.id==='knowledge-card-search'){knowledgeCardView().search=e.target.value;document.getElementById('knowledge-card-catalogue').innerHTML=knowledgeCardList();}if(e.target.closest?.('#knowledge-card-editor')){const value=captureKnowledgeEditor();if(value){value.d.dirty=true;const status=document.getElementById('knowledge-card-save-status');if(status)status.textContent='Unsaved changes';}}});
document.addEventListener('change',e=>{if(e.target.id==='knowledge-card-type'||e.target.id==='knowledge-card-status'){knowledgeCardView()[e.target.id.endsWith('type')?'type':'status']=e.target.value;refreshKnowledgeCatalogue();}if(e.target.id==='knowledge-card-editor-type'){const value=captureKnowledgeEditor();if(value){value.d.type=e.target.value;value.d.dirty=true;document.getElementById('knowledge-card-fields').innerHTML=knowledgeCardFields(value.d);document.getElementById('knowledge-card-fields').closest('details').querySelector('summary').textContent=knowledgeCardDetailsTitle(value.d.type);document.getElementById('knowledge-card-type-hint').textContent=knowledgeCardInfo().types[value.d.type]?.hint||knowledgeCardHints[value.d.type];}}});
document.addEventListener('submit',e=>{if(e.target.id==='knowledge-card-editor'){e.preventDefault();saveKnowledgeCardEditor().then(()=>{render();toast('Building block saved privately.');}).catch(error=>toast(error.message));}});

function knowledgePacketContent(r,packet){const b=r.body,privateCard=r.kind==='domain-implication',p=privateCard?b.payload:b,type=privateCard?b.card?.type||knowledgeCardMeta(r).type:b.type,fields=privateCard?b.card?.fields||{}:b.fields||{},links=privateCard?b.card?.relations||[]:b.relations||[],evidence=p.evidence||[],title=raw=>{const v=packet.records.find(v=>label(v.ref)===label(raw));return referenceText(raw,v||{ref:raw});};return `<p class="caption">${esc(knowledgeCardInfo().types[type]?.label||type)} · ${privateCard?'Private selected block':'Shared for review'}</p>${para(p.statement)}${p.rationale?val('Rationale and limits',p.rationale):''}${Object.entries(fields).filter(([,v])=>v).map(([k,v])=>val(knowledgeCardInfo().types[type]?.fields[k]||k,v)).join('')}${links.length?`<h4>Related blocks and project context</h4>${links.map(l=>`<p><strong>${esc(knowledgeCardInfo().relations[l.relation]||l.relation)}:</strong> ${esc(title(l.ref))}</p>${para(l.rationale)}${l.conditions?val('Applies when',l.conditions):''}${sourceDetails(l.ref)}`).join('')}`:''}<details><summary>Evidence (${evidence.length})</summary>${evidence.map(e=>{const raw=e.ref||knowledgeParseRef(e.source);return `<blockquote>${esc(e.quote||'PDF page '+e.page)}</blockquote><p class="caption">${esc(title(raw))}</p>${sourceDetails(raw)}`;}).join('')||'<p class="caption">No independent source cited. This remains working interpretation.</p>'}</details><p class="caption">${privateCard?'Private authored knowledge.':'Publication retains authorship and versions; it does not approve a requirement.'}</p>`;}

document.addEventListener('toggle',e=>{const k=e.target.dataset?.knowledgeDisclosure;if(k&&e.target.isConnected){const v=knowledgeCardView();v.sections??={};v.sections[k]=e.target.open;}},true);

let knowledgeLinkSource=null;
function knowledgeLinkContent(r){const b=r.body;knowledgeLinkSource=r;const header=`<p class="caption">${esc(referenceText(r.ref,r))} · Saved version · Read only</p>${sourceDetails(r.ref)}`;if(r.kind==='domain-implication'||r.kind==='knowledge-card')return header+knowledgePacketContent(r,{records:[r]});if(r.kind==='source'&&b.visual_pdf&&typeof visualPageUrl==='function')return header+`<label class="form-field"><span>Page</span><select id="knowledge-link-page">${Array.from({length:b.visual_pdf.page_count},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select></label><figure class="knowledge-link-image"><img id="knowledge-link-image" src="${esc(visualPageUrl(r.ref,1))}" alt="${esc(b.title)} · PDF page 1"><figcaption>Retained static page. This does not establish tested behavior.</figcaption></figure>`;return header+para(b.statement||b.text||b.claim||b.observation||b.outcome||b.question||'')+(b.acceptance_criteria?val('Acceptance criteria',b.acceptance_criteria):'')+(b.conditions?val('Applies when',b.conditions):'');}
document.addEventListener('change',e=>{if(e.target.id==='knowledge-link-page'&&knowledgeLinkSource){const page=Number(e.target.value),image=document.getElementById('knowledge-link-image');image.src=visualPageUrl(knowledgeLinkSource.ref,page);image.alt=knowledgeLinkSource.body.title+' · PDF page '+page;}});

// Transient capture: choose a destination, inspect one section, then explicitly save.
let knowledgeCapture=null;
function knowledgeCaptureSections(type){return {statement:type==='finding'?'Finding':'What this block captures',rationale:'Rationale and uncertainty',...Object.fromEntries(Object.entries(knowledgeCardInfo().types[type]?.fields||{}).map(([k,v])=>['fields.'+k,v]))};}
function knowledgeCaptureSelection(capture){return capture.review?{review:capture.review,path:capture.path,text:capture.text}:{turn:capture.turn,text:capture.text};}
function knowledgeCaptureRow(){return knowledgeCapture?.existing?knowledgeCards().find(r=>r.ref.id===knowledgeCapture.card):null;}
function knowledgeCaptureBefore(row,section){return row?(section.startsWith('fields.')?row.body.card?.fields?.[section.slice(7)]||'':row.body.payload[section]||''):'';}
function knowledgeCaptureAfter(before,passage){return before?before+'\n\n'+passage:passage;}
function knowledgeCaptureContext(){if(!knowledgeCapture||knowledgeCapture.capture.key!==chatKey())throw Error('Select the passage again in its original chat.');return knowledgeCapture;}
function openKnowledgeCapture(capture,existing=false){
 if(capture.key!==chatKey())throw Error('Select the passage again in its original chat.');
 const cards=knowledgeCards().filter(r=>r.body.status==='held');
 if(existing&&!cards.length)throw Error('Save a block first, or choose New block.');
 knowledgeCapture={capture,existing,card:cards[0]?.ref.id||'',type:knowledgeCardView().type&&knowledgeCardView().type!=='implication'?knowledgeCardView().type:'note',title:capture.text.trim().slice(0,100),section:'statement',summary:'',phase:'choose'};
 knowledgeCaptureChoose();
}
function knowledgeCaptureChoose(){
 const d=knowledgeCaptureContext(),cards=knowledgeCards().filter(r=>r.body.status==='held'),row=knowledgeCaptureRow();if(row)d.type=knowledgeCardMeta(row).type;
 if(!knowledgeCaptureSections(d.type)[d.section])d.section='statement';
 modal(d.existing?'Add to block':'New block',`<p class="caption">${d.capture.review?'Selected review passage':'Selected chat passage'}</p><blockquote class="knowledge-capture-excerpt">${esc(d.capture.text)}</blockquote>${d.existing?`<label class="form-field"><span>Block</span><select id="knowledge-capture-card" name="block">${cards.map(r=>`<option value="${esc(r.ref.id)}" ${r.ref.id===d.card?'selected':''}>${esc(r.body.payload.title)} · ${esc(knowledgeCardInfo().types[knowledgeCardMeta(r).type]?.label||'Card')}</option>`).join('')}</select></label>`:`<label class="form-field"><span>Type</span><select id="knowledge-capture-type" name="type">${knowledgeCardTypeChoices().map(([k,t])=>`<option value="${k}" ${d.type===k?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><label class="form-field"><span>Title</span><input name="title" id="knowledge-capture-title" maxlength="200" required value="${esc(d.title)}"></label>`}<label class="form-field"><span>Section</span><select id="knowledge-capture-section" name="section">${Object.entries(knowledgeCaptureSections(d.type)).map(([k,v])=>`<option value="${k}" ${d.section===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p class="caption">Review the wording before saving. Response text remains working knowledge.</p><footer class="dialog-foot"><button type="button" data-close>Cancel</button><button type="submit">Review change</button></footer>`,null,null,{className:'knowledge-capture-dialog',footer:false});
 document.getElementById('modal-form').addEventListener('submit',e=>{e.preventDefault();try{knowledgeCaptureReview(new FormData(e.target));}catch(error){document.querySelector('#modal .error').textContent=error.message;}});
}
function knowledgeCaptureReview(fd){
 const d=knowledgeCaptureContext();d.phase='review';d.section=fd.get('section');
 if(!d.existing){d.type=fd.get('type');d.title=fd.get('title').trim();}else d.card=fd.get('card');
 const row=knowledgeCaptureRow();if(d.existing&&!row)throw Error('Reopen the block before adding this passage.');
 if(row){const edit=knowledgeCardEdits.get(knowledgeCardEditKey(row.ref.id));if(edit?.dirty)throw Error('Save or discard this block’s open edits before adding a passage.');d.type=knowledgeCardMeta(row).type;d.expected={...row.ref};}
 const sectionLabel=knowledgeCaptureSections(d.type)[d.section];if(!sectionLabel)throw Error('Choose a section of this block.');
 const destination=[d.card,d.type,d.section].join('|');d.before=knowledgeCaptureBefore(row,d.section);if(d.destination!==destination)d.after=knowledgeCaptureAfter(d.before,d.capture.text);d.destination=destination;
 knowledgeCapturePreview();
}
function knowledgeCapturePreview(){
 const d=knowledgeCaptureContext(),row=knowledgeCaptureRow(),section=knowledgeCaptureSections(d.type)[d.section],limit=d.section==='statement'?4000:d.section==='rationale'?1500:2000;
 modal('Review block change',`${d.reason?`<p class="knowledge-placement-reason caption">${esc(d.reason)}</p>`:''}<p class="knowledge-capture-destination"><strong>${esc(row?.body.payload.title||d.title)}</strong><br><span class="caption">${esc(knowledgeCardInfo().types[d.type]?.label||d.type)} · ${esc(section)}</span></p>${d.existing?`<section class="knowledge-capture-before"><h3>Current</h3><p class="pre">${esc(d.before||'Empty section')}</p></section>`:''}${!d.existing&&d.section!=='statement'?`<label class="form-field"><span>${d.type==='finding'?'Finding':'What this block captures'}</span><textarea name="summary" required maxlength="4000" rows="3" placeholder="Summarize the concept this block holds.">${esc(d.summary)}</textarea></label>`:''}<label class="form-field"><span>${d.existing?'After saving':'Content'}</span><textarea name="text" id="knowledge-capture-text" required maxlength="${limit}" rows="6">${esc(d.after)}</textarea></label><p class="caption">${d.section==='fields.evidence_notes'?'Evidence notes retain the discussion; add independent source citations on the block.':d.existing?'Only this section changes. Existing links and source citations stay intact.':'Saved privately. Add source citations and connections on the block.'}</p><details class="knowledge-capture-origin"><summary>Selected passage</summary><blockquote>${esc(d.capture.text)}</blockquote></details>`, 'Save block',async fd=>{
  knowledgeCaptureContext();const text=fd.get('text'),summary=fd.get('summary')||'';
  const payload={expected:d.expected||null,conversation:chatThread().ref,type:d.existing?undefined:d.type,title:d.existing?undefined:d.title,statement:summary,section:d.section,text,selection:knowledgeCaptureSelection(d.capture),confirm:true};
  const signature=JSON.stringify(payload);if(signature!==d.requestSignature){d.requestSignature=signature;d.request_id=crypto.randomUUID();}
  const out=await command('knowledge-card-capture',{...payload,request_id:d.request_id});knowledgeCardEdits.delete(knowledgeCardEditKey(out.ref.id));knowledgeCardView().newCard=null;knowledgeCardView().open=out.ref.id;domainPanels.set(chatKey(),'implications');if(d.fromCarry)clearKnowledgeCarry();knowledgeCapture=null;return out;
 },{className:'knowledge-capture-dialog',footerActions:'<button type="button" class="compact-text-action" data-action="kc-capture-back">Back</button>'});
}
function knowledgeCaptureHistory(row){const entries=row.body.captures||[];if(!entries.length)return '';return `<details class="knowledge-card-section"><summary>Saved passages (${entries.length})</summary>${entries.slice().reverse().map(e=>`<p class="caption">${e.origin.review?'Review response':e.origin.role==='user'?'User message':'AI partner response'} · ${esc(knowledgeCaptureSections(knowledgeCardMeta(row).type)[e.section]||e.section)} · ${esc(date(e.at))}</p><blockquote>${esc(e.origin.text)}</blockquote>`).join('')}<p class="caption">Retained as provenance, not independent evidence.</p></details>`;}
document.addEventListener('change',e=>{
 if(!['knowledge-capture-card','knowledge-capture-type'].includes(e.target.id)||!knowledgeCapture)return;
 const d=knowledgeCaptureContext();const title=document.getElementById('knowledge-capture-title');if(title)d.title=title.value;
 if(e.target.id==='knowledge-capture-card'){d.card=e.target.value;d.type=knowledgeCardMeta(knowledgeCaptureRow()).type;}else d.type=e.target.value;
 d.section='statement';const select=document.getElementById('knowledge-capture-section');select.innerHTML=Object.entries(knowledgeCaptureSections(d.type)).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('');
});

// Optional advice and an ephemeral picked-up passage; clipboard behavior stays native.
let knowledgeCarry=null;
function knowledgeCarryState(){
 if(knowledgeCarry?.key!==chatKey())knowledgeCarry=null;
 document.body?.classList?.toggle('knowledge-carrying',!!knowledgeCarry);
 return knowledgeCarry;
}
function clearKnowledgeCarry(){knowledgeCarry=null;document.body?.classList?.remove('knowledge-carrying');}
function knowledgeCarryChip(){const p=knowledgeCarryState();return p?`<div class="knowledge-carry-chip" role="status"><div><strong>Picked up</strong><p>${esc(p.text.slice(0,100))}${p.text.length>100?'…':''}</p><span class="caption">Choose a block, then a section.</span></div><button type="button" class="compact-text-action" data-action="kc-carry-cancel">Cancel</button></div>`:'';}
function knowledgeCarryPick(capture){
 if(capture.key!==chatKey())throw Error('Select the passage again in its original chat.');
 const v=knowledgeCardView();if(v.newCard&&hasUnsavedKnowledgeCards())throw Error('Save or discard the new block before picking up a passage.');
 knowledgeCarry={...capture};v.open=null;v.newCard=null;v.status='held';v.search='';domainPanels.set(chatKey(),'implications');hideThoughtSelection();render();
 document.getElementById('knowledge-card-search')?.focus();
}
function knowledgeDropLabel(section,title){
 const carry=knowledgeCarryState();return carry?`<button type="button" class="knowledge-drop-section" data-action="kc-carry-drop" data-id="${esc(section)}" aria-label="Place picked-up text in ${esc(title)}">${esc(title)} <span aria-hidden="true">＋</span></button>`:`<span>${esc(title)}</span>`;
}
function knowledgePlacements(){return knowledgeCardInfo().placements||[];}
function knowledgePrimeText(origin,text){
 knowledgeCarryState();const p=knowledgePlacements().find(p=>label(p.origin.review)===label(origin?.review)&&JSON.stringify(p.origin.path)===JSON.stringify(origin.path)&&text.includes(p.quote));
 if(!p)return esc(text);
 const i=text.indexOf(p.quote),section=knowledgeCaptureSections(p.type)[p.section]||'Card';
 const destination=p.target?'Add to '+p.title+' → '+section:'New '+(knowledgeCardInfo().types[p.type]?.label||'card');
 return esc(text.slice(0,i))+`<mark class="knowledge-prime" data-action="kc-suggested" data-id="${esc(p.id)}" aria-label="Suggested block placement: ${esc(destination)}" title="${esc(destination)} · Review before saving">${esc(p.quote)}<button type="button" class="knowledge-prime-action" data-action="kc-suggested" data-id="${esc(p.id)}" aria-label="Suggested block placement: ${esc(destination)}" title="${esc(destination)} · Review before saving"><svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true"><path d="M3 2.5h8v11H3zM5 5h4M5 7.5h4M5 10h2" fill="none" stroke="currentColor" stroke-width="1.2"/></svg></button></mark>`+esc(text.slice(i+p.quote.length));
}
function knowledgePlacementReview(p,carry=false){
 const capture={...p.origin,text:p.text||p.quote,key:chatKey()};
 const row=p.target?knowledgeCards().find(r=>label(r.ref)===label(p.target)):null;
 if(p.target&&!row)throw Error('This block changed. Choose its current version before placing the passage.');
 knowledgeCapture={capture,existing:!!row,card:row?.ref.id||'',type:row?knowledgeCardMeta(row).type:p.type,title:p.title||capture.text.trim().slice(0,100),section:p.section,summary:p.card_statement||'',reason:p.reason||'',phase:'choose',fromCarry:carry};
 const values={card:knowledgeCapture.card,type:knowledgeCapture.type,title:knowledgeCapture.title,section:p.section};
 knowledgeCaptureReview({get:k=>values[k]});
}
function knowledgeCarryDrop(section){
 const capture=knowledgeCarryState();if(!capture)throw Error('Pick up a passage first.');
 const row=knowledgeCards().find(r=>r.ref.id===knowledgeCardView().open);if(!row)throw Error('Choose a saved block first.');
 knowledgePlacementReview({origin:knowledgeCaptureSelection(capture),text:capture.text,target:row.ref,type:knowledgeCardMeta(row).type,title:row.body.payload.title,section},true);
}
async function knowledgePlacementAction(action,id){
 if(action==='kc-carry-cancel'){clearKnowledgeCarry();render();return true;}
 if(action==='kc-carry-drop'){knowledgeCarryDrop(id);return true;}
 if(action==='kc-suggested'){
  if(window.getSelection?.()?.toString().trim())return true;
  const p=knowledgePlacements().find(p=>p.id===id);if(!p)throw Error('Select a current block suggestion.');knowledgePlacementReview(p);return true;
 }
 if(action==='kc-new'&&knowledgeCarryState()){openKnowledgeCapture(knowledgeCarryState(),false);knowledgeCapture.fromCarry=true;return true;}
 return false;
}
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&knowledgeCarryState()){clearKnowledgeCarry();if(!document.querySelector('dialog[open]'))render();}
 const target=e.target.closest?.('.knowledge-prime');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const p=knowledgePlacements().find(p=>p.id===target.dataset.id);if(p)try{knowledgePlacementReview(p);}catch(error){toast(error.message);}}
});

function knowledgeCardAssessment(id){
 const row=knowledgeCards().find(r=>r.ref.id===id);if(!row)throw Error('Choose a saved block.');
 if(knowledgeCardEdits.get(knowledgeCardEditKey(id))?.dirty)throw Error('Save this block’s edits before asking for an assessment.');
 const d=chatDraft(),prompt='Assess the block “'+row.body.payload.title+'”. Recommend the most useful optimizations to its clarity, concept/type fit, evidence and limits, implications and connections. Explain what to change and why; propose wording or missing-evidence questions. Keep the block unchanged until I review and save an update.';
 if(!d.assessmentCard||label(d.assessmentCard)!==label(row.ref)){
  if((d.text+'\n\n'+prompt).length>3000)throw Error('Send or shorten the current message before adding this block assessment.');
  d.text=d.text.trim()?d.text+'\n\n'+prompt:prompt;
 }
 d.assessmentCard={...row.ref};d.assessmentTitle=row.body.payload.title;d.purpose='explore';render();document.getElementById('domain-chat-message')?.focus();
}
